INSERT INTO Bar (name, address) VALUES ('Bar1', '456 Oak Ave');
INSERT INTO Beer (name, brewer) VALUES ('BeerA', 'Brewer1');
INSERT INTO Beer (name, brewer) VALUES ('BeerB', 'Brewer2');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'Bar1', 3);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'BeerA', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'BeerB', 6.00);
INSERT INTO Likes (drinker, beer) VALUES ('Alice', 'BeerA');

